  //  shield 누른 때부터 받는 피해 감소 시간(실제 초 · 지쳐 동작이 느려져도 늘지 않음) · shieldCut 그동안 칼날 상처 감소(동방 막기와 같은 칸 50 %) · dealt 찌르는 동안 주는 피해 몫
