  itOppositionVals: { shield: realS(.6), shieldCut: .5, dealt: .6, aim: .10, extend: .28, hold: .12, recover: .16, pull: .10, reach: .42, turn: .65, side: .04, lead: .15, leadMax: .2 },
  itForte: 0, // 이탈리아 forte 막기 연구 후보 (가) (10/17 감독 요청 — **연구 · 사장님 확인 전**, 확인표 2037): 0 = 끔(지금 판 그대로 — 이탈리아 막기 몸꼴 덧씌우기 없음) · 1·2 = 후보 몸꼴(schools.js ITALIAN_FORTE — 위 줄을 팔 뻗은 원전 꼴로 세워 forte 로 받게). `?itForte=1`, 시뮬 with_config.mjs SKILL.itForte=1 · parry_gap_map.mjs '무기:forte'·'무기:forte2' — docs/strike/italian_forte_parry_2026-10-17.md
  // 플레이어 막기 버튼 거듦 (10/12 — 사장님 01:1x '무기가 무거울수록 성공률이 너무 떨어져서 거의 무용지물 … 지금보다는 성공률이 올라야 해'. docs/strike/parry_assist_2026-10-12.md · 확인표 990~993, **사장님 확인 전**).
  //  막기 버튼을 누르고 있는 동안만, 플레이어만(src/parry_button.js). AI 막기·시뮬 판은 읽지 않는다. 새 상한·쿨타임 없음.
  //  단계: 0 = 끔(10/11 판 그대로, `?parryAssist=0`) · 1 = 무게 보정(손 빠르기·서보 힘) · 2 = 1 + 일찍 읽기 · 3 = 2 + 자리에서 칼 세우기 덧힘
  parryFollow: 1, // 10/16 22:5x 막기 단추 따라가기 (사장님 '요략세 … 바로 적용') — 막는 중 위협이 잠깐 끊기면(상대가 준비 자세에서 멈춤) 기다릴 때 규칙(ai.js coverFor)으로 상대 칼이 있는 쪽 줄로 옮긴다. 0 = 10/16 까지(한 공격에 한 줄 — 준비 동작을 공격으로 읽어 굳힘). 빈틈 지도: 유파 막기 73 → 76 % · 기본 72 → 76 % (docs/strike/yoryak_shape_2026-10-16.md)
  parryAssist: 0, // 디렉터 10/12 04:0x 병합 때 기본 0(끔): 시뮬에서 '무거울수록 못 막음'이 다시 나오지 않았고 1~3 단계 모두 95 % 띠 안 · 브라우저 츠바이핸더 1 단계 2/6(0 단계 9/11) — 사장님 장면 확인 뒤 다시 정함. 전 작업자 추천은 1 = 무게 보정만 (롱소드보다 가벼운 칼은 바이트까지 10/11 그대로). 2·3 은 재 봐도 띠 안이고 츠바이핸더에서 나빠 보이는 판이 있어 기본에서 뺌 — 확인표 990 사장님 확인 전
  parryAssistVals: {
    iRef: 0.28, // 무게 잣대: 손 기준 휘두름 관성(fighter.swordIhand, kg·m²). 롱소드 0.272 · 모노호시자오 0.328 · 에스톡 0.363 · 츠바이핸더 0.787 · 북부 대공의 검 1.027. 이보다 무거운 몫 w = I / iRef − 1 (0~wMax) 에만 보탬 → 롱소드까지(세이버·레이피어·청강검…)는 그대로
    wMax: 2,
    speedK: 0.5, // ① 손 빠르기: parrySpeed × (1 + speedK·w)
    powK: 0.5, // ① 서보 힘: powerMul = 1 + powK·w (손목 힘 한도·칼 무게 버팀 — 막기 버튼이 손을 쥔 동안만)
    lead: 0.1, // ② 일찍 읽기: 들어오는 칼끝·타격점을 lead 초 앞으로 내다봐 위협을 읽는다 (threatNow 의 0.45 s 앞 원통을 그만큼 넓힘). 무게와 상관없이
    reread: true, // ② 다시 읽기: 한 공격 안에서 읽은 줄이 바뀌면 막기 자리도 바꾼다 (AI·10/11 버튼은 한 공격에 한 번 정한다 — 준비 동작을 공격으로 읽으면 틀린 줄을 굳힘)
    holdK: 0.5, // ③ 자리 덧힘: 막는 줄의 자리에 손이 닿아 있는 동안 powerMul 에 × (1 + holdK·(1 + w)) — 맞고 밀리지 않게
    holdR: 0.04, // ③ '자리에 닿음' = 손 목표가 막기 자리에서 이 안 (패드 m)
  },
  // 동방 막기 단추 손 빠르기 (10/17 19:0x 사장님 승인 — 동방 막기 최종 검토 §4 의 2 '동방 막기 단추의 손 옮김 빠르기만 조금 올리기' · **스위치 · 판 값 1 = 끔**,
  //  docs/strike/chinese_parry_speed_2026-10-17.md · 확인표 2065~ 사장님 확인 전): 동방 막기 책을 쥔 플레이어(무기 유파 chinese · 막기 책 사용 — me.schoolParry !== false)의
  //  막기 단추가 손 목표를 옮기는 빠르기(AI_LEVELS.normal.parrySpeed 4.5 m/s — 모든 유파 같은 값)에 이 배율을 곱한다(src/parry_button.js).
  //  AI 막기 · 다른 유파 · 책 없음 · 막기 자리 · 몸꼴 · 줄 읽기 · 비기 손 빠르기는 그대로. `?cnParrySpeed=1.3` · 시뮬 with_config.mjs SKILL.cnParrySpeedK=1.3 · parry_gap_map.mjs 꼴 'cn1.3'
  cnParrySpeedK: 1,
  // 동방 막기 마지막 안 두 가지 (10/17 20:1x 사장님 '그런 방식으로도 막기가 강화될 수 없다면, (동방 유파에만) 막는 힘에 버티는 힘 보너스를 주거나 막는 동안 피해 감소 효과를 부여하는 방안을
  //  마지막으로 검토해' — 연구 스위치, docs/strike/chinese_parry_brace_2026-10-17.md · 확인표 2067~. **버티는 힘은 끔 · 피해 감소는 판 값 0.5(사장님 10/17 22:1x)**). 둘 다 동방 막기 책을 쥔 플레이어(parry_button.js chineseBook)의
  //  막기 단추가 **막는 중**(mode 'defend' — 새 공격을 읽은 때부터 '공격이 지나갔다' 또는 막기 시간 0.65 s 까지)일 때만. 기다림 · AI 막기 · 다른 유파 · 책 없음은 그대로. 새 상한 · 문턱 · 쿨타임 없음:
  //  cnBraceK = 버티는 힘: 서보 힘 me.powerMul × (1 + cnBraceK) — 손목이 칼을 세워 두는 힘 한도(fighter.driveSword str — 막기 거듦 ①③ 과 같은 칸, 곱). `?cnBrace=0.5` · 시뮬 with_config.mjs SKILL.cnBraceK=0.5 · 빈틈 지도 꼴 'cnB0.5'
  //  cnParryDmgCut = 막는 동안 피해 감소: 그때 입는 칼날 상처(베기 · 찌르기) 심각도 × (1 − cut) — combat.js analyze(팔다리 기능 · 피 흘림 · 의식 · 죽음 문턱이 모두 심각도에서 나옴 ·
  //   칼과 몸의 물리 — 가르나 튕기나 · 충격 · 휘청임 — 는 그대로). `?cnParryCut=0.25` · 시뮬 with_config.mjs SKILL.cnParryDmgCut=0.25 · 꼴 'cnD0.25'
  cnBraceK: 0,
  cnParryDmgCut: 0.5, // **판 값 0.5 — 사장님 10/17 22:1x '본판에 50%로 적용할게 너무 과한 거 같으면 나중에 조정하겠음'** (확인표 2068 · 버티는 힘 cnBraceK 는 그대로 끔)
  // 일본 · 이베리아 막는 동안 피해 감소 (사장님 10/18 22:1x '동방에서 막기 중 피해 50% 감소처럼, 일본과 이베리아도 막기 중 피해 20% 감소 부여' · docs/strike/japanese_flow_adopt_2026-10-18.md):
