    press: realS(0.6), // 때맞춤 (s): 막기 단추를 새로 누른 뒤 이 안에 칼이 닿아야 — 사장님 10/24 12:2x '0.4초 안 -> 0.6초로'(시간 사다리 0.6 · 전 0.4)
