  planRelease: 0.2,
  // 사람 제비 베기 세 해법 (사장님 10/25 21:1x '해법 1~3 좋아' — "제비베기는 지금보다 최소 10배 이상 세져야 해 … 의도적으로 중력과 관성을 역행해서 상대의 허를 찌르는 기술인데
  //  지금은 중력과 관성의 영향을 고스란히 받고 있어" · 기록 docs/strike/tsubame_snap_2026-10-25.md · 확인표 2570 ~ 2576). 사람 강화(unique_assist.js — PLAYER_UNIQUE japanese tsubameGaeshi)만 · AI 제비 베기는 그대로.
  //  ① tsuRuler: 끝 힘 잣대 길이를 꺾은 자리부터(올려 긋는 길 길이) — 전엔 내려베기 몫 길이라 짧은 올려 긋기가 그만큼 못 가고 맞아 끝 힘이 0 ~ 3 % 만 켜졌다. 0 = 전 판 `?tsuRuler=0`
  tsuRuler: 1,
  //  ② tsuSnap: 꺾는 순간 내려가던 칼의 기세를 지우고 올려 긋는 길을 고노센 발도 칼끝 빠르기(secret_instant.js iaiTipSpeed)의 specialShare.tsubameGaeshi 몫으로 tsuSnapTime 초까지 끌고 간다 —
  //   비기 · 진 · 츠바메가에시와 같은 운동학 틀(requestCombo — 맞음은 쓸린 자리의 실제 빠르기 · 판정 배율 1 · 끝 자세 붙잡기 없이 곧장 손가락에 돌려줌). 무기 비검 kin(모노호시자오 진)이 있으면 그것이 먼저. 0 = 전 판 `?tsuSnap=0`
  tsuSnap: 1,
  //  칼끝 빠르기 = specialShare.tsubameGaeshi 0.6 (고노센 칼끝의 몫 — 10/25 결정 tsuSnapShare 0.6 그대로 · 10/29 02:0x 한 표로)
  tsuSnapTime: 0, // 11/01 00:xx 사장님 '공격이 몇 초 안에 끝나야한다 이런 기준 없애라고 햇지 내가 그딴건 필요없어' → 0 = 상한 없음(길 끝까지 · 확인표 3276) · 전: 끌고 가는 시간 상한 (s — 시간 사다리 0.2 반응) — 사장님 10/25 결정. 길이 먼저 끝나면 거기서 끝
  //  ③ tsuAim: 올려 긋는 길 끝을 다리에서 상대 아래팔 · 겨드랑이 · 가슴 높이로 (PLAYER_UNIQUE tsubameGaeshi aim 칸 — 사람 표만 · schools.js AI 길 그대로) + 손 돌리기 덧칸(곁눈 베기 같은 길 덧칸 planStep)으로
  //   손목을 사람 범위 안에. 0 = 전 판 `?tsuAim=0`
  tsuAim: 1,
  //  ③ 몸통 띠 (사장님 10/25 23:1x '제비베기는 위팔·가슴을 노리기보다 자연스럽게 몸통 전체(다리 위 골반부터 목 아래 가슴까지)를 노리게' · 확인표 2586 · 2587 · 2589): 1 = 가슴 높이 끝 점에 맞춘 덧칸 대신
  //   올려 긋는 길을 미리 끌고 가 보아 처음 닿을 곳이 몸통 띠(다리 위 골반 ~ 목 아래 가슴) 밖이면 길 높이를 가장 적게 옮김(secret_instant.js comboBandShift · bandFirst — 내려간 칼이 멈춘 자리 · 상대 자세에 따라
  //   배 · 골반 · 가슴으로 흩어짐) + 운동학 칼 굴림 묶음(날이 앞장서되 손목 밧줄 HUMAN.forearmRoll 까지만 — placeIai). 0 = 10/25 21:1x 판(`?tsuBand=0`). tsuAim 0 이면 읽지 않음
  tsuBand: 1,
  //  ③ 곧은 길 (사장님 10/31 16:xx '제비 베기는 곧은 길로 바꿔' — 기록 docs/strike/tsubame_straight_2026-10-31.md · 확인표 3230): 0 = 꺾은 자리에서 왼 위로 곧게 한 번(unique_assist.js TSU_AIM.line —
  //   몸통 띠 · 날 앞장 · 굴림 묶음 그대로) · 1 = 10/25 갈고리 길(TSU_AIM.band — 칼 든 쪽으로 나갔다 가슴 가운데로 되돌아옴) `?tsuHook=1`. tsuAim 0 · tsuBand 0 이면 읽지 않음
  tsuHook: 0,
  // 위에서 내려 찌르기(이탈리아) — 옷 · 갑옷 틈을 파고드는 값(combat.js THRUST_STYLE gap 자리)을 이 찌르기만 이 값으로 (레이피어 기본 0.3 · 사장님 10/21 '파고드는 값 0.6으로 해' · 확인표 2107)
  imbroccataGap: 0.6,
