  //  탭 찌르기 덧씌우기로 찌른다(AI 임브로카타 ai.js startStrike → skill.thrust 와 같은 길 — 이탈리아 찌르기 THRUST.itLunge: 몸통 겨눔 · 팔만으로 안 닿으면 거리만큼 런지) · 그 탭의 찌른 상처에 I8 틈 파고들기 그대로.
  //  0 = 전 판(손가락 길만 — 칼끝이 머리 곁 18 cm · 가슴 곁 26 cm 를 옆으로 쓸고 지나감) `?imbroReach=0`. 같은 날 의논한 이어 찌르기 조건 · 빠르기 보정 · 잔상 · 길은 사장님 10/28 00:5x 결정으로 칼끝 돌려 빼기(I9 — 아래 cav*)로 옮김
  imbroReach: 1,
  // 10/31 12:xx 사장님 'I7은 어떤 방향이나 높이에서든 다른 유파의 내려 긋는 베기에 해당하는 커맨드를 내려찌르기로 전환해 주도록 하자. 어차피 지금 이탈리아 수직 베기는 거의 공격으로서 의미가 없잖아' (사람 I7 · AI 그대로):
  //  아래로 가는 긋기 = 손가락 첫 방향이 곧장 아래에서 이 각(°) 안 — 90 − 22.5(칸 입력 도식의 수평 띠 '축에서 22.5° 안이면 수평' — skill_tree_data.js NODE_CMD 머리말 · 새 수 없음): 곧장 아래 ↓ · 사선 아래 ↙/↘ 모두 · 수평 · 올려 긋기는 아님 ·
  //  0 = 끔(전 판 — 황소 찌르기 긋기만) `?imbroDown=0`
  imbroDown: 67.5,
  // 사람 칼끝 돌려 빼기 (I9 카바치오네 — 이탈리아 특수 공격 · 사장님 10/28 00:5x '그렇게 해' — 기록 docs/strike/cavazione_2026-10-28.md · 확인표 2701 ~ 2707 · 2708). 사람 강화(unique_assist.js)만 · AI 카바치오네는 그대로.
  //  ① cavTap: 막아찌르기(I6 — 막기 단추 새 누름의 짧은 찌르기 · italian_opposition.js)가 상대에게 상처(심각도 > 0)를 못 내고 끝난 때(다 마침 · 끊김 — 헛침 · 막힘 · 칼끼리 맞닿음 모두)부터
  //   cavFrom ~ cavTo 초(실제 0.6 ~ 1.2 s) 사이의 탭 = 보통 탭 찌르기 대신 칼끝 돌려 빼기. cavFrom 보다 이른 탭은 보통 탭 찌르기이고 그 기회를 없앰(탭을 연달아 두드리면 나가지 않게) ·
  //   상처를 낸 막아찌르기 · 보통 찌르기('그냥 찌르기 x') 뒤의 탭 · 창 밖 탭은 보통 탭 찌르기 · 전 판 입력(찌르기 맞물림 · 꺾음 뒤 긋기)은 사람 몫에서 뺌(AI 그대로).
  //   비기 창(리솔루토)이 열려 있으면 그 탭은 비기가 먼저(main.js). 0 = 끔 `?cavTap=0` — 사장님 10/28 00:5x · 01:1x · 01:2x 결정
  cavTap: 1,
