  //  끝에서 탭까지 p50 0.27 s 라 탭 99 번이 모두 0.6 s 전(이른 탭 — 71 번이 기회를 없앰) · 창 안 0 · 나감 0 → 걸림돌은 박자(0.6 s 기다림). 0.6 → 0.2(시간 사다리 0.2 '반응')로 당김:
  //  같은 봇 창 안 81 · 나감 판당 0 → 2.14 · 0.4 는 아직 0 · 더 늦게(0.4 ~ 0.6 s · 0.65 ~ 1.05 s) 치는 사람도 창 안 그대로. 이른 탭(0.2 s 전 — 연타)이 기회를 없애는 규칙 · 창 끝 1.2 는 그대로 ·
  //  옛 판 `?cavFrom=0.6` (실제 초)
  cavFrom: realS(0.2), // 막아찌르기가 끝난 때부터 이 초가 지나야 (시간 사다리 0.2) — 10/28 01:0x · 01:2x 0.6 → [사장님 10/29 20:0x 결정 '둘 중 하나를 완화' · 값 0.2 는 감독(잰 것) — 확인 전]
  // 막기 단추를 쥔 채 친 탭 (10/30 00:4x 사장님 '카바치오네 혹시 거리 제한이 있는가? 너의 조건은 다 이해했는데 한번도 안나감.' — 고친 버그 · 확인표 2939): 1 = 받음 —
  //  막기 단추를 쥐고 있으면(막아찌르기를 낸 그 손가락 · F 키) 탭이 늘 버려졌다(main.js 가 강화에 '막기가 손을 쥠'으로 알림 → busy). 쥔 채 친 탭은 막기가 놓아 주는 공격(main.js G.broken)이라
  //  칼끝 돌려 빼기 탭은 손이 정말 쥐였나(막기가 손을 쥠 · 미리 받기)만 봄 · 브라우저(실제 터치 · 키) 떼고 탭 3 / 3 나감 · 쥔 채 탭 0 / 3 → 고친 뒤 9 / 9 (tools/browser/cavazione_probe.mjs) · 싸움(쥔 채 탭 봇 21 판) 나감 0 → 판당 1.29. 0 = 전 판 `?cavHeld=0`
  cavHeld: 1, // [사장님 10/30 08:2x 결정 '모르트슐라크 카바치오네 수정 넣어.']
  // 날개 접기(C6) · 겹치기(G7) 탭도 막기 단추를 쥔 채 받음 (사장님 10/30 08:2x '날개접기랑 겹치기도 같게해' — 확인표 2992 답 · 2998): cavHeld 와 같은 길(손이 정말 쥐였나 handHeld 만 봄). 0 = 전 판 `?tapHeld=0`
  tapHeld: 1, // [사장님 10/30 08:2x 결정]
  cavTo: realS(1.2), // 막아찌르기가 끝난 때부터 이 초까지 (시간 사다리 1.2 — 사장님 10/28 01:1x '시간사다리에 1.2를 추가하고 카바치오네 0.6-1.2 사이로 해' · 01:0x 판 1.3) · `?cavTo=` (실제 초)
  //  ② cavSnap: 탭으로 낸 칼끝 돌려 빼기 = 상대 칼 밑으로 칼끝을 돌려 빼(상대 칼이 없는 쪽으로) 가슴(목 아래 ~ 가슴 위 띠)을 곧게 찔러 뻗음 — 제비 베기 되돌림 칼과 같은 운동학 틀
  //   (secret_instant.js requestArtThrust · requestCombo — 맞음은 쓸린 자리의 실제 빠르기 · 판정 배율 1 · 끝 자세 붙잡기 없이 곧장 손가락에 · 잔상 = 연환 잔상). 0 = 탭 찌르기 덧씌우기로만 `?cavSnap=0`
  cavSnap: 1,
