  // 시간 상한을 세기 시작하는 때 (10/30 — 사장님 '카바치오네 혹시 거리 제한이 있는가?' · 고친 버그 · 사장님 10/30 08:2x 결정 '수정 넣어' · 확인표 2990): 1 = 찌르는 토막부터(돌려 빼기 · 겨눔 토막은 셈 밖 —
  //  날개 접기 · 풍차 베기 capFromCut 과 같은 셈 · 같은 빠르기 · 값 0.2 그대로). 0 = 전 판(내는 때부터 — 레이피어 가슴 사이 1.4 m 안이면 돌려 빼기 · 겨눔이 0.2 s 를 다 써 찌름 없이 끝남 =
  //  숨은 가장 가까운 거리) `?cavCapCut=0`
  cavCapCut: 1, // [사장님 10/30 08:2x 결정 '모르트슐라크 카바치오네 수정 넣어.']
  cavSnapTime: 0, // 11/01 00:xx 사장님 '공격이 몇 초 안에 끝나야한다 이런 기준 없애라고 햇지 내가 그딴건 필요없어' → 0 = 상한 없음(길 끝까지 · 확인표 3276) · 전: 끌고 가는 시간 상한 (실제 초 — 시간 사다리 0.2) · tsuSnapTime 과 같은 수(그쪽은 표준 시간 기록 §2 경계 2 로 게임 초 그대로 — 여쭐 것) · 사장님 10/28 00:5x 결정. 길(약 0.1 s)이 먼저 끝나면 거기서 끝
  // ── 10/31 이탈리아 자리 바꿈 (사장님 10/31 12:xx '카바치오네가 발전해서 리솔루토가 되는 게 더 멋지고' · '지금 안대로 해. 인콰르타타에 잔상과 궤적도 넣고 특수공격 대접을 해줘야 해 알지? 카바치오네는 이제 특수공격이 아니고.'
  //    — 기록 docs/strike/italian_swap_2026-10-31.md · 확인표 3240 ~ 3259) ──
