  //   ① 조건(cavTap · 사장님 원문 '내 칼이 상대 칼과 닿았을 때 박자에 맞춰 찌르면 발동 … 베기에서의 닿음이나 막힘은 빼야'): 내 칼이 상대 칼에 실제로 닿은 때(combat.js bladeClash 가 적는 feel.touching —
  //    가까움만으로는 아님) — 내 찌르기(탭 · 찌르는 긋기)가 상대 칼에 부딪힘 · 막기 자세(공격 안 함)에서 그냥 닿음 · 상대가 내 칼을 누르거나 묶음 · 내 찌르기가 막힘 모두 —
