  //    내 긋기(찌르기 아닌 휘두름 · 끌고 가는 베는 칼)가 도는 동안 닿은 닿음은 셈 밖(그 닿음 통째 — 재기 stats.touchCut) · 창 값 cavFrom · cavTo 그대로(위 · 사장님 값)
  //   ② 그 칼 = 위 cavSnap 길(돌려 빼기 → 겨눔 → 찌름) · 칼끝 빠르기 = 보통 탭 찌르기 빠르기(cavSpeed 'tap' = (THRUST.reach + THRUST.chamber) ÷ THRUST.extend — 탭 찌르기가 뻗는 몫 그대로 · 새 수 없음) ·
  //    잔상 없음 · 식힘 없음. 비킨 쪽 cavSide: 'contact' = 닿았을 때 상대 칼이 있던 쪽(feel.normal 의 반대 — 상대 칼 밑을 지나 그 너머 열린 줄로) · 'free' = 10/28 판(내는 때 상대 칼이 없는 쪽)
  cavSpeed: 'tap', // [감독 해석 — '보통 찌르기 빠르기' 사장님 10/31 · 수 확인 전] · 숫자(m/s)를 주면 그 빠르기 · `?cavSpeed=`
